import { hub, proactive, service } from '@jibo/interfaces';
import * as common from '@jibo/utils-common';
import * as WebSocket from 'ws';
import { AudioConfig } from './session/AudioStreamSession';
import { ListenClientSession } from './session/ListenClientSession';
import { ProactiveClientSession } from './session/ProactiveClientSession';
const jsonwebtoken = require('jsonwebtoken');


export interface CloudRequestOptions {
    path: string;
    hostname: string;
    port: number;
    auth?: {
        secret: string; // this is jsonwebtoken secret
        credentials: service.IAuthDetails; // here are credentials
    } | string; // Authenticated Bearer token
}

export interface ASRRequestOptions extends CloudRequestOptions {
    audioPath: string;
}

const SECURE_PORTS = [ 443 ];

export class Client {

    public static async startListenSession(options: CloudRequestOptions, request: hub.request.ListenMessageData, audio?: AudioConfig): Promise<ListenClientSession> {
        const ws = await Client.openWebsocket(options);
        const session = new ListenClientSession(request, common.getUUID(), ws, audio);
        session.start();
        return session;
    }

    public static async startProactiveSession(options: CloudRequestOptions, request: proactive.ProactiveRequestData) {
        const ws = await Client.openWebsocket(options);
        const session = new ProactiveClientSession(request, common.getUUID(), ws);
        session.start();
        return session;
    }

    /**
     * Opens up a websocket connection with the cloud
     */
    private static openWebsocket(options: CloudRequestOptions): Promise<WebSocket> {
        let authToken = '';
        if (options.auth) {
            // If "options.auth" is the token itself then we use directly, otherwise we
            // create signed token using jsonwebtoken
            authToken = (typeof options.auth === 'string') ?
                options.auth :
                jsonwebtoken.sign(options.auth.credentials, options.auth.secret);
        }

        return new Promise((resolve, reject) => {
            const path = options.path.startsWith('/') ? options.path : '/' + options.path;
            const protocol = (SECURE_PORTS.indexOf(options.port) > -1) ? 'wss' : 'ws';
            const transID = 'tid:' + common.getUUID();
            const uri = `${protocol}://${options.hostname}:${options.port}${path}`;
            const ws = new WebSocket(uri, {
                headers: {
                    Authorization: `Bearer ${authToken}`,
                    [service.Headers.transID]: transID
                }
            });

            ws.on('open', () => {
                resolve(ws);
            });

            ws.on('error', (e) => {
                reject(e);
            });
        });
    }

    // TODO?: add a POST connection parallel to websocket

}
