import { Duplex } from 'stream';


/**
 * A duplex stream element that buffers input data and only dispatches it out at a given
 * frequency with a given chunk size. </br>
 * Can be used to simulate real-time captured audio from a file stream for example.
 */
export class DispatchStream extends Duplex {

    private queue: Buffer[] = [];
    private writeIndex = 0;
    private inputDone = false;
    private intervalHandle: any;
    private hasStoppedWriting = false;
    private zeroArray: number[];


    /**
     * Creates an instance of DispatchStream.
     * @param delayMs The interval at which to dispatch chunks of audio
     * @param [chunkSize=4] The chunk size of bytes to dispatch every time
     */
    constructor(private intervalMs: number, private chunkSize = 4, streamZerosAfter = false) {
        super();

        this.zeroArray = new Array<number>(this.chunkSize);
        for (let i = 0; i < this.chunkSize; i++) {
            this.zeroArray[i] = 0;
        }

        this.on('pipe', (stream) => {
            stream.on('end', () => {
                this.inputDone = true;
            });

            this.intervalHandle = setInterval(() => {
                if (this.writeIndex < this.queue.length) {
                    this.push(this.queue[this.writeIndex]);
                    this.writeIndex++;
                }

                // If we are done with all input data
                if (this.inputDone && this.writeIndex === this.queue.length) {
                    if (streamZerosAfter) {
                        this.push(new Buffer(this.zeroArray));
                    } else {
                        if (!this.hasStoppedWriting) {
                            this.hasStoppedWriting = true;
                            this.push(null);
                        }
                        this.cleanup();
                    }
                }
            }, this.intervalMs);
        });
    }

    _write(chunk, enc, cb) {
        for (let i = 0; i < chunk.length; i += this.chunkSize) {
            let end = Math.min(i + this.chunkSize, chunk.length);
            this.queue.push(new Buffer(chunk.slice(i, end)));
        }
        cb();
    }

    _read() {
        // intentionally empty
    }

    stop() {
        if (!this.hasStoppedWriting) {
            this.hasStoppedWriting = true;
            this.push(null);
        }
        this.cleanup();
    }

    private cleanup() {
        if (this.intervalHandle) {
            clearInterval(this.intervalHandle);
            this.intervalHandle = null;
        }
    }
}
