import { Transform } from 'stream';

const INT16_MAX = 32767;


export class NoiseTransform extends Transform {

    private noiseAmplitude: number;

    /**
     * @param noiseRatio The ratio of noise. Range 0-1
     */
    constructor(noiseRatio: number) {
        super();
        this.noiseAmplitude = noiseRatio * INT16_MAX;
    }

    _transform(buf: Buffer, encoding, callback: ()=>void): void {
        const out = new Buffer(buf.length);

        // Iterate the 16bit chunks
        for (let i = 0; i < buf.length; i += 2) {
            const val = buf.readInt16LE(i);
            const random = Math.random() * 2 * this.noiseAmplitude - this.noiseAmplitude;
            let outVal = Math.floor(val + random);

            // Cap 
            outVal = Math.min(INT16_MAX, outVal);
            outVal = Math.max(-INT16_MAX, outVal);

            // write those 2 bytes into the other buffer
            out.writeInt16LE(outVal, i);
        }

        // return the buffer with the changed values
        this.push(out);
        callback();
    }
}
