import * as WebSocket from 'ws';
import { EventEmitter } from 'events';
import { hub, nlu, service } from '@jibo/interfaces';
import * as common from '@jibo/utils-common';
import { AudioStreamSession, AudioConfig } from './AudioStreamSession';
import { SessionEvents, EventHandler } from './SessionEvents';

export import ListenResponseData = hub.response.ListenResponseData;


export interface ListenEvents extends EventEmitter {
    on(event: 'SOS', listener: EventHandler<void>): this;
    removeListener(event: 'SOS', listener: EventHandler<void>): this;
    emit(event: 'SOS', data: void): boolean;

    on(event: 'EOS', listener: EventHandler<void>): this;
    removeListener(event: 'EOS', listener: EventHandler<void>): this;
    emit(event: 'EOS', data: void): boolean;

    on(event: 'LISTEN', listener: EventHandler<ListenResponseData>): this;
    removeListener(event: 'LISTEN', listener: EventHandler<ListenResponseData>): this;
    emit(event: 'LISTEN', data: ListenResponseData): boolean;
}


export class ListenClientSession extends AudioStreamSession {

    public events: ListenEvents & SessionEvents;

    private mode: hub.request.ListenMessageMode;

    constructor(private request: hub.request.ListenMessageData, transactionID: string, ws: WebSocket, audio?: AudioConfig) {
        super(transactionID, ws, audio);
        this.mode = request.mode;
    }

    public start() {
        super.start();

        // We first sanitize the data a little
        this.request.rules = this.request.rules.map(context => context.toLowerCase());

        this.write({
            type: hub.request.MessageType.LISTEN,
            ts: Date.now(),
            msgID: common.getUUID(),
            data: this.request
        } as hub.request.ListenMessage);

        this.startDispatchingAudio();
    }

    writeClientASR(asrText: string) {
        const message: hub.request.ClientASRMessage = {
            type: hub.request.MessageType.CLIENT_ASR,
            ts: Date.now(),
            msgID: common.getUUID(),
            data: {
                text: asrText
            }
        };
        this.write(message);
    }

    writeClientNLU(nlu: nlu.NLUResult) {
        const message: hub.request.ClientNLUMessage = {
            type: hub.request.MessageType.CLIENT_NLU,
            ts: Date.now(),
            msgID: common.getUUID(),
            data: nlu
        };
        this.write(message);
    }

    protected handleMessage(message: service.BaseResponse<any, any>): void {
        const type: hub.response.MessageType = message.type;
        switch (type) {
            case hub.response.MessageType.EOS:
                this.events.emit('EOS', undefined);
                break;
            case hub.response.MessageType.SOS:
                this.events.emit('SOS', undefined);
                break;
            case hub.response.MessageType.LISTEN:
                this.events.emit('LISTEN', message.data);
                break;
            default:
                this.events.emit('ERROR', new Error(`ListenClientSession: Didn't recognize message type '${type}'`));
        }
    }
}
