import * as fs from 'fs';
import { Stream, Duplex } from 'stream';
import * as WebSocket from 'ws';
import { DispatchStream } from '../audio/DispatchStream';
import { NoiseTransform } from '../audio/NoiseTransform';
import { ClientSession } from './ClientSession';


function createBufferStream(buffer: Buffer): Duplex {
    const stream = new Duplex();
    stream.push(buffer);
    stream.push(null);
    return stream;
}


export interface AudioConfig {
    path?: string;
    buffer?: Buffer;
    noise?: number;
}


export abstract class AudioStreamSession extends ClientSession {

    private dispatchStream: DispatchStream;

    constructor(transactionID: string, ws: WebSocket, private audio?: AudioConfig) {
        super(transactionID, ws);
    }

    startDispatchingAudio() {
        // We start streaming audio to the cloud
        if (this.audio) {
            if (!this.audio.buffer && !this.audio.path) {
                throw new Error(`Must provide either audio buffer or file path`);
            }
            this.audio.noise = this.audio.noise || 0;
            // Assumes 16kHz 16bit signed PCM
            this.dispatchStream = new DispatchStream(100, 4 * 1600, true);
            const readStream = this.audio.path ?
                fs.createReadStream(this.audio.path) :
                createBufferStream(this.audio.buffer);
            let stream: Stream = readStream.pipe(this.dispatchStream);
            if (this.audio.noise) {
                stream = stream.pipe(new NoiseTransform(this.audio.noise));
            }
            stream.on('data', (chunk: Buffer) => {
                this.ws.send(chunk);
            });
        }
    }

    public start() {
        const stopStreaming = () => {
            if (this.dispatchStream) {
                this.dispatchStream.stop();
                this.dispatchStream = null;
            }
        };

        // Here we stop the audio stream if it hasn't been stopped already
        this.transactionDone = this.transactionDone
            .then(() => {
                stopStreaming();
            }).catch((error) => {
                stopStreaming();
                throw error;
            });
    }
}
