import * as WebSocket from 'ws';
import { EventEmitter } from 'events';
import { hub, service } from '@jibo/interfaces';
import * as common from '@jibo/utils-common';
import { SessionEvents } from './SessionEvents';


export abstract class ClientSession {

    public transactionDone: Promise<void>;
    public events: SessionEvents;

    private closed = false;

    constructor(public transactionID: string, protected ws: WebSocket) {
        const transactionExtPromise = new common.ExtPromise<void>();
        this.transactionDone = transactionExtPromise.promise;
        this.events = new EventEmitter();

        // Here we stop the websocket once the promise is resolved
        this.transactionDone = this.transactionDone.then(() => {
            this.close();
        }).catch(error => {
            this.close();
            throw error;
        });

        this.ws.on('message', (mes) => {
            try {
                const mesObj: hub.response.Response<any, any> = JSON.parse(mes.toString());
                if (mesObj.type === hub.response.MessageType.ERROR) {
                    return transactionExtPromise.reject(new Error(common.getErrorMessage(mesObj.data)));
                }
                // We emit every message on the incoming event
                this.events.emit('ALL', mesObj);
                // Then we emit specific events for certain messages
                switch (mesObj.type) {
                    case hub.response.MessageType.SKILL_REDIRECT:
                        this.events.emit('SKILL_REDIRECT', mesObj.data);
                        break;
                    case hub.response.MessageType.SKILL_ACTION:
                        this.events.emit('SKILL_ACTION', mesObj.data);
                        break;
                    default:
                        // Subclass has to handle message
                        this.handleMessage(mesObj);
                }

                if (mesObj.final) {
                    transactionExtPromise.resolve(undefined);
                }
            } catch (error) {
                transactionExtPromise.reject(error);
            }
        });

        this.ws.on('error', (error) => {
            transactionExtPromise.reject(error);
        });
    }

    /**
     * Should write the corresponding start message for this kind of session
     */
    public abstract start();

    public close() {
        if (!this.closed) {
            this.ws.close();
            this.closed = true;
        }
    }

    /**
     * Write context message to hub
     * @param {hub.request.ContextData} context
     */
    public writeContext(context: hub.request.ContextData) {
        this.write({
            type: hub.request.MessageType.CONTEXT,
            ts: Date.now(),
            msgID: common.getUUID(),
            data: context
        } as hub.request.ContextMessage);
    }

    /**
     * Writes an arbitrary message to Hub
     * @param {service.BaseMessage} message
     */
    protected write(message: service.BaseMessage<any, any>) {
        this.ws.send(JSON.stringify(message));
    }

    /**
     * To be implemented by subclasses.
     * Handles messages that are not handled in base class. Should throw exception if
     * message is not recognized.
     * @param {service.BaseResponse} message
     */
    protected abstract handleMessage(message: service.BaseResponse<any, any>): void;
}
