import { EventEmitter } from 'events';
import { ClientSession } from './ClientSession';
import { hub, proactive, service } from '@jibo/interfaces';
import ProactiveResponseData = proactive.ProactiveResponseData;
import * as common from '@jibo/utils-common';
import * as WebSocket from 'ws';
import { SessionEvents, EventHandler } from './SessionEvents';


export interface ProactiveEvents extends EventEmitter {
    on(event: 'PROACTIVE', listener: EventHandler<ProactiveResponseData>): this;
    removeListener(event: 'PROACTIVE', listener: EventHandler<ProactiveResponseData>): this;
    emit(event: 'PROACTIVE', data: ProactiveResponseData): boolean;
}


export class ProactiveClientSession extends ClientSession {

    public events: ProactiveEvents & SessionEvents;

    constructor(private request: proactive.ProactiveRequestData, transactionID: string, ws: WebSocket) {
        super(transactionID, ws);
    }

    public start() {
        this.write({
            type: hub.request.MessageType.TRIGGER,
            ts: Date.now(),
            msgID: common.getUUID(),
            data: this.request
        } as proactive.ProactiveRequest);
    }

    protected handleMessage(message: service.BaseResponse<any, any>): void {
        const type: hub.response.MessageType = message.type;
        switch (type) {
            case hub.response.MessageType.PROACTIVE:
                this.events.emit('PROACTIVE', message.data);
                break;
            default:
                this.events.emit('ERROR', new Error(`ProactiveClientSession: Didn't recognize message type '${type}'`));
        }
    }
}
